using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWithSubtotal100Pays95()
    {
        var types = typeof(ApplicationMarker).Assembly.GetTypes()
            .Concat(typeof(DomainMarker).Assembly.GetTypes())
            .Where(t => t.Name.Contains("Checkout") || t.Name.Contains("Pricing"));

        Assert.True(types.Any(), "No checkout/pricing type exists, so the payable total (expected 95.00) cannot be calculated.");
    }
}
